// Helper function to count how many strings in a sequence start with a given prefix
function CountStringsWithPrefix(strings: seq<string>, prefix: string): int
    requires strings != null
    requires prefix != null
    ensures 0 <= CountStringsWithPrefix(strings, prefix) <= |strings|
{
    var count := 0;
    var i := 0;
    while i < |strings|
        invariant 0 <= i <= |strings|
        invariant count == CountStringsWithPrefix(strings[..i], prefix)
    {
        if strings[i].StartsWith(prefix) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

